let ComputerInventory = materialize(
    ConfigurationChange
    | where isnotempty(Computer)
    | where "*" in ({ComputerFilter}) or Computer in ({ComputerFilter})
    | summarize LastComputerSeen = max(TimeGenerated) by Computer
);
let LatestSetting = materialize(
    ConfigurationChange
    | where ValueName == "ForceDefenderPassiveMode"
    | where "*" in ({ComputerFilter}) or Computer in ({ComputerFilter})
    | summarize arg_max(TimeGenerated, *) by Computer
    | extend ModeFilter = iff(ChangeCategory !~ "Removed" and trim(" ", tostring(ValueData)) == "1", "Passive", "Active")
    | project Computer, ModeFilter
);
let Counts = ComputerInventory
    | join kind=leftouter LatestSetting on Computer
    | extend ModeFilter = coalesce(ModeFilter, "Active")
    | summarize Computers = dcount(Computer) by ModeFilter;
datatable(ModeFilter:string, Mode:string, SortOrder:int) [
    "Passive", "Passive Mode", 1,
    "Active", "Active Mode", 2
]
| join kind=leftouter Counts on ModeFilter
| extend Computers = coalesce(Computers, 0)
| order by SortOrder asc
| project Mode, Computers, ModeFilter
